setup_sql:
CREATE TABLE stations (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE readings (id INTEGER PRIMARY KEY, station_id INTEGER, value INTEGER);
INSERT INTO stations (id, name) VALUES (1, 'North'), (2, 'South'), (3, 'East'), (4, 'West');
INSERT INTO readings (id, station_id, value) VALUES (1, 1, 10), (2, 1, NULL), (3, 2, 20), (4, 2, 20), (5, 2, 0), (6, NULL, 30);

questions.sql:
SELECT value FROM readings
WHERE station_id = 2
ORDER BY id;

SELECT id FROM readings
WHERE value >= 20
ORDER BY id;

SELECT id FROM readings
WHERE value = NULL
ORDER BY id;

SELECT id FROM readings
WHERE value IS NULL
ORDER BY id;

SELECT COUNT(*) AS joined_rows
FROM stations AS s
INNER JOIN readings AS r ON r.station_id = s.id;
